        // Validate required fields
        if (!config.project || !config.variables) {
          res.writeHead(400, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({
            status: 'error',
            message: 'Missing required fields: project, variables'
          }));
          return;
        }

        // Send success response
        const response = {
          status: 'accepted',
          message: 'Configuration received and logged for audit compliance',
          audit_id: `AUDIT-${new Date().toISOString().replace(/[-:T]/g, '').substring(0, 14)}`,
          timestamp: new Date().toISOString()
        };

        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify(response, null, 2));

      } catch (error) {
        console.error('Error parsing JSON:', error.message);
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({
          status: 'error',
          message: `Invalid JSON: ${error.message}`
        }));
      }
    });

  } else {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({
      status: 'error',
      message: 'Endpoint not found'
    }));
  }
});

