const PORT = 47301;

const server = http.createServer((req, res) => {
  if (req.method === 'POST' && req.url === '/api/deploy-config') {
    let body = '';

    req.on('data', chunk => {
      body += chunk.toString();
    });

    req.on('end', () => {
      try {
        const config = JSON.parse(body);
        const timestamp = new Date().toISOString();
        const project = req.headers['x-deploy-project'] || 'Unknown';
        const deployTime = req.headers['x-deploy-timestamp'] || 'Unknown';

        // Log the received configuration
        console.log('\n' + '='.repeat(60));
        console.log('📋 DEPLOYMENT CONFIG RECEIVED');
        console.log('='.repeat(60));
        console.log(`Timestamp: ${timestamp}`);
        console.log(`Project: ${project}`);
        console.log(`Deploy Time: ${deployTime}`);
        console.log('\nConfiguration:');
        console.log(JSON.stringify(config, null, 2));
        console.log('='.repeat(60) + '\n');

        // Send success response
        const response = {
          status: 'success',
          message: 'Configuration received and logged for audit',
          config_id: `deploy-${new Date().toISOString().replace(/[:.]/g, '-')}`,
          variables_count: Object.keys(config).length
        };

        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify(response));

      } catch (error) {
        console.error('❌ Error: Invalid JSON received:', error.message);
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ status: 'error', message: 'Invalid JSON' }));
      }
    });
  } else {
    res.writeHead(404);
    res.end();
  }
});

